def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import numpy as np
    x = np.asarray(history, dtype=float)
    if horizon <= 0:
        return []
    if x.size == 0:
        return [0.0] * horizon
    if x.size < 8:
        return [float(np.median(x))] * horizon
    period = 24 if 'hour' in frequency.lower() else max(2, min(24, x.size // 3))
    lags = [p for p in (period, 2 * period, 3 * period) if x.size >= p + 12]
    baseline_window = min(period, x.size)
    origins = list(range(max(4, x.size - 3 * period), x.size))
    base_errors = []
    for t in origins:
        if t > 0:
            base_errors.append(abs(x[t] - np.median(x[max(0, t - baseline_window):t])))
    base_score = float(np.median(base_errors)) if base_errors else float('inf')
    best_lag = None
    best_score = base_score
    for lag in lags:
        errors = []
        for t in origins:
            if t >= lag:
                width = min(period, t - lag, t)
                if width > 0:
                    offset = np.median(x[t - width:t] - x[t - lag - width:t - lag])
                else:
                    offset = 0.0
                errors.append(abs(x[t] - (x[t - lag] + offset)))
        if errors:
            score = float(np.median(errors))
            if score < best_score:
                best_score = score
                best_lag = lag
    if best_lag is None:
        level = float(np.median(x[-baseline_window:]))
        return [level] * horizon
    width = min(period, x.size - best_lag)
    offset = float(np.median(x[-width:] - x[-best_lag-width:-best_lag])) if width > 0 else 0.0
    out = []
    extended = list(map(float, x))
    for k in range(horizon):
        value = extended[len(extended) - best_lag] + offset
        if not np.isfinite(value):
            value = float(np.median(x[-baseline_window:]))
        extended.append(float(value))
        out.append(float(value))
    return out
